import {renderHTML as diffHTML} from './components/PIIDiffViewer.svelte.html.js';
import {renderHTML as reviewHTML} from './components/PIIReviewModal.svelte.html.js';
import {renderHTML as fragmentHTML} from './components/PIIDiffFragment.svelte.html.js';

export interface PIIDiffFragmentView {
  kind: 'word' | 'line' | 'panel'; className?: string; slot: string;
}
const OPEN = '<!--[-->', CLOSE = '<!--]-->', EMPTY = '<!---->';
const LEFT = 'getbased-pii-private-left', RIGHT = 'getbased-pii-private-right';
const MOBILE = 'getbased-pii-private-mobile';
const INITIAL = 'getbased-pii-private-initial', CONTENT = 'getbased-pii-private-content';
function checksum(value: string): string {
  let hash = 5381, i = value.length;
  while (i) hash = ((hash << 5) - hash) ^ value.charCodeAt(--i);
  return (hash >>> 0).toString(36);
}
function unique(html: string, needle: string): number {
  const start = html.indexOf(needle);
  if (start < 0 || html.lastIndexOf(needle) !== start) throw new Error('Unexpected PII private coordinate');
  return start;
}
function root(html: string): string {
  if (!html.startsWith(OPEN) || !html.endsWith(CLOSE)) throw new Error('Unexpected PII SSR root');
  return html.slice(OPEN.length, -CLOSE.length);
}
// Actual server compilation owns these two root-leading anchors. Each complete
// coordinate includes the original whitespace and the static modal opening tag.
const REVIEW_START = EMPTY + '\n      <div class="pii-diff-modal pii-review-modal" role="dialog" aria-modal="true" aria-label="PII Review">';
const DIFF_START = EMPTY + '\n    <div class="pii-diff-modal" role="dialog" aria-modal="true" aria-label="Privacy Diff">';
function modalRoot(html: string, coordinate: string): string {
  const skeleton = root(html);
  if (!skeleton.startsWith(coordinate) || skeleton.lastIndexOf(coordinate) !== 0) throw new Error('Unexpected PII modal start coordinate');
  return skeleton.slice(EMPTY.length);
}
function privateSlot(html: string, sentinel: string): string {
  const candidates = [EMPTY + sentinel + EMPTY, '<!--' + checksum(sentinel) + '-->' + sentinel + EMPTY];
  const found = candidates.filter(value => html.includes(value));
  if (found.length !== 1) throw new Error('Unexpected PII private HTML envelope');
  unique(html, found[0]!); return found[0]!;
}
// Resolve every coordinate on the private skeleton before inserting escaped
// diff tokens or controller-produced fragments. Inserted data is never rescanned.
function insert(skeleton: string, values: readonly (readonly [string, string])[],
  exact: readonly (readonly [string, string])[] = []): string {
  const coordinates = [...values.map(([sentinel, value]) => [privateSlot(skeleton, sentinel), value] as const), ...exact];
  const edits = coordinates.map(([needle, value]) => {
    const start = unique(skeleton, needle);
    return {start, end: start + needle.length, value};
  }).sort((a, b) => a.start - b.start);
  let cursor = 0, output = '';
  for (const edit of edits) {
    if (edit.start < cursor) throw new Error('Overlapping PII private coordinates');
    output += skeleton.slice(cursor, edit.start) + edit.value; cursor = edit.end;
  }
  const residue = skeleton.slice(cursor);
  const privateRemainder = edits.reduce((text, edit) => text.replace(skeleton.slice(edit.start, edit.end), ''), skeleton);
  if (privateRemainder.includes('<!--')) throw new Error('Unqualified PII skeleton marker');
  return output + residue;
}
function fragment(view: Omit<PIIDiffFragmentView, 'slot'>, html: string): string {
  let skeleton = root(fragmentHTML({view: {...view, slot: CONTENT}}));
  const marker = view.kind === 'word' ? '<!--[0-->' : view.kind === 'panel' ? '<!--[1-->' : '<!--[-1-->';
  if (!skeleton.startsWith(marker) || !skeleton.endsWith(CLOSE)) throw new Error('Unexpected PII fragment branch');
  skeleton = skeleton.slice(marker.length, -CLOSE.length);
  return insert(skeleton, [[CONTENT, html]]);
}
export function renderPIIWord(kind: 'removed' | 'added', escapedText: string): string {
  return fragment({kind: 'word', className: 'pii-word-' + kind}, escapedText);
}
export function renderPIILine(kind: 'equal' | 'removed' | 'added', html: string): string {
  return fragment(kind === 'equal' ? {kind: 'line'} : {kind: 'line', className: 'pii-diff-highlight-' + kind}, html);
}
export function renderPIIOriginalPanel(html: string): string { return fragment({kind: 'panel'}, html); }
export function renderPIIDiffViewer(left: string, right: string): string {
  return insert(modalRoot(diffHTML({slots: {left: LEFT, right: RIGHT}}), DIFF_START), [[LEFT, left], [RIGHT, right]]);
}
export function renderPIIReviewModal(left: string, initial: string, streaming: boolean): string {
  let skeleton = modalRoot(reviewHTML({slots: {left: LEFT, mobile: MOBILE, initial: INITIAL}, streaming}), REVIEW_START);
  for (const name of ['thinking', 'status', 'stop', 'retry']) {
    const open = '<getbased-pii-private-' + name + '>', close = '</getbased-pii-private-' + name + '>';
    const start = unique(skeleton, open), end = unique(skeleton, close);
    if (end <= start) throw new Error('Malformed PII conditional coordinate');
    const inside = skeleton.slice(start + open.length, end), marker = streaming ? '<!--[0-->' : '<!--[-1-->';
    if (!inside.startsWith(marker) || !inside.endsWith(CLOSE)) throw new Error('Unexpected PII conditional branch');
    const content = inside.slice(marker.length, -CLOSE.length);
    if (content.includes('<!--') || (!streaming && content !== '')) throw new Error('Unexpected PII conditional content');
    skeleton = skeleton.slice(0, start) + content + skeleton.slice(end + close.length);
  }
  // Svelte owns native textarea serialization; the private sentinel supplies its
  // initial value. Qualify the complete observed textarea before inserting the
  // controller's already escaped text, retaining original HTML/value semantics.
  const textareaOpen = '<textarea class="pii-edit-textarea" id="pii-edit-textarea" spellcheck="false"'
    + (streaming ? ' readonly=""' : '') + '>';
  return insert(skeleton, [[LEFT, left], [MOBILE, left]],
    [[textareaOpen + INITIAL + '</textarea>', textareaOpen + initial + '</textarea>']]);
}

